/* Original starter revision notes. Review and extend against your current NEB syllabus before relying on them for exams. */
window.STUDY_NOTES = [
{ id:"a12-company",level:"Class 12",subject:"Accountancy",title:"Meaning and features of a company",chapter:"Company Accounts · Fundamentals",tags:"company definition separate legal entity perpetual succession limited liability",summary:"Understand a company as a legally incorporated business organisation and revise its main characteristics.",sections:[
["Meaning of a company",`A company is an incorporated association of persons formed under the applicable company law to carry on lawful business. After registration, it has a legal identity separate from its members.`],
["Main features",`<ul><li><b>Separate legal entity:</b> the company is legally distinct from its shareholders.</li><li><b>Limited liability:</b> in a limited company, members' liability is generally limited to the unpaid amount on their shares or the amount guaranteed.</li><li><b>Perpetual succession:</b> changes in membership do not by themselves end the company's existence.</li><li><b>Common capital:</b> share capital may be raised by issuing shares, subject to law and the company's documents.</li><li><b>Transfer of shares:</b> transfer rules depend on the company type and applicable law.</li><li><b>Separate property:</b> company assets belong to the company, not directly to individual shareholders.</li></ul>`],
["Advantages",`A company can pool capital from investors, continue despite changes in membership, divide ownership into shares and provide limited liability where the law permits.`],
["Limitations",`Incorporation and compliance can be costly; legal reporting requirements may be extensive; decision-making can be slower; and ownership and management may be separated.`],
["Exam answer",`A company is an incorporated legal entity distinct from its members. Its key features include separate legal identity, perpetual succession, limited liability where applicable, and ownership of property in its own name.`]
]},
{ id:"a12-public-private",level:"Class 12",subject:"Accountancy",title:"Public company and private company",chapter:"Company Accounts · Company types",tags:"public private company differences shares members",summary:"Compare public and private companies using ownership, share transfer and fundraising rules.",sections:[
["Private company",`A private company is a company whose constitution and applicable law restrict public invitations to subscribe for its shares and may restrict share transfers. The exact statutory requirements depend on the jurisdiction.`],
["Public company",`A public company is a company that is not classified as private under the relevant company law. Subject to legal requirements, it may raise capital from the public.`],
["Key differences",`<ul><li><b>Public invitation:</b> a public company may offer securities to the public when legally permitted; a private company cannot freely make a public offer.</li><li><b>Share transfer:</b> private-company documents often restrict transfer; public-company shares are generally more transferable, subject to applicable rules.</li><li><b>Disclosure:</b> public companies generally face more extensive disclosure and compliance requirements.</li><li><b>Capital raising:</b> public companies can have wider fundraising options.</li></ul>`],
["Exam tip",`Write the definition first, then compare the companies under clear headings. Use the precise legal limits and terminology in your prescribed textbook.`]
]},
{ id:"a12-moa",level:"Class 12",subject:"Accountancy",title:"Memorandum of Association (MOA)",chapter:"Company Accounts · Company formation",tags:"memorandum association moa clauses objectives registered office capital liability",summary:"Learn the purpose of the MOA and the common clauses discussed in company-law courses.",sections:[
["Meaning",`The Memorandum of Association (MOA) is a foundational document that states essential information about a company, including its name, registered office, objectives and capital or liability details as required by law.`],
["Common clauses",`<ul><li><b>Name clause:</b> gives the registered name of the company.</li><li><b>Registered office clause:</b> identifies the legally registered office or jurisdiction as required.</li><li><b>Objective clause:</b> states the company's purposes or permitted activities where required.</li><li><b>Liability clause:</b> explains the liability of members.</li><li><b>Capital clause:</b> states authorised capital information when applicable.</li><li><b>Subscription clause:</b> records the initial subscribers and their agreement to form the company.</li></ul>`],
["Importance",`The MOA helps define the company's legal framework and informs members and outsiders about key aspects of the company's constitution.`],
["MOA and AOA",`The MOA sets out foundational company information and scope; the Articles of Association (AOA) generally describe internal management rules. Their exact legal effects depend on the governing law.`]
]},
{ id:"a12-equity",level:"Class 12",subject:"Accountancy",title:"Equity shares",chapter:"Company Accounts · Share capital",tags:"equity shares ordinary shareholders dividend voting rights residual",summary:"Revise the meaning, characteristics, advantages and risks of equity shares.",sections:[
["Meaning",`Equity shares are ordinary ownership shares in a company. Equity shareholders generally bear the residual risk and may receive dividends when declared according to law and company decisions.`],
["Characteristics",`<ul><li>They represent ownership interest.</li><li>Dividend is not normally a fixed contractual return like interest on a loan.</li><li>Voting rights usually allow participation in specified company decisions.</li><li>Equity shareholders receive the residual claim after creditors and prior-ranking claims, subject to law.</li><li>Equity capital generally does not have a fixed repayment date while the company continues.</li></ul>`],
["Advantages and risks",`Equity finance can strengthen a company's capital base without fixed interest payments. However, existing ownership may be diluted, dividends are uncertain, and shareholders can lose some or all of their investment.`],
["Exam answer",`Equity shares represent ordinary ownership in a company. Their holders generally have voting rights, receive dividends only when declared, and bear the residual risk of the business.`]
]},
{ id:"a12-forfeiture",level:"Class 12",subject:"Accountancy",title:"Forfeiture and reissue of shares",chapter:"Company Accounts · Journal entries",tags:"forfeiture shares nonpayment application allotment calls share capital securities premium reissue",summary:"Understand why shares may be forfeited and the basic accounting treatment.",sections:[
["Meaning of forfeiture",`Forfeiture of shares is the cancellation of a member's shares by the company for failure to pay amounts due, when the company's articles and applicable law allow it and the required procedure has been followed.`],
["Accounting idea",`On forfeiture, Share Capital is debited with the called-up amount on the forfeited shares. Unpaid allotment or call amounts are credited to their relevant accounts. Share Forfeiture is credited with the amount previously received on share capital, subject to the applicable treatment of any premium.`],
["Securities premium",`If premium became due but was not received, its treatment differs from premium already received. Follow the journal-entry rules and assumptions used in the prescribed textbook question; do not automatically treat all premium as forfeiture profit.`],
["Reissue",`Forfeited shares may be reissued under the applicable rules. A discount on reissue cannot exceed the amount available in the Share Forfeiture Account for those shares under the standard textbook treatment. Any eligible surplus remaining after reissue is transferred to Capital Reserve.`],
["Working-note checklist",`<ol><li>Find the called-up share capital on the forfeited shares.</li><li>Separate amounts received from amounts unpaid.</li><li>Check whether securities premium was due and whether it was received.</li><li>Record the forfeiture entry.</li><li>For reissue, calculate cash received and discount, then transfer any eligible balance to Capital Reserve.</li></ol>`]
]},
{ id:"a12-pro-rata",level:"Class 12",subject:"Accountancy",title:"Oversubscription and pro-rata allotment",chapter:"Company Accounts · Issue of shares",tags:"oversubscription prorata pro rata allotment application money excess application",summary:"Revise oversubscription and the basic proportion used in pro-rata allotment questions.",sections:[
["Oversubscription",`Oversubscription occurs when applications received for shares exceed the number of shares offered by a company.`],
["Pro-rata allotment",`Pro-rata allotment means allotting shares proportionately among eligible applicants when the company cannot allot the full number requested, subject to the issue terms and applicable rules.`],
["Basic ratio",`If 60,000 shares are applied for and 30,000 shares are allotted proportionately, the ratio is 30,000 : 60,000 = 1 : 2. An applicant who applied for 200 shares would be allotted 100 shares under that simple ratio.`],
["Excess application money",`Application money received for shares not allotted may be refunded or adjusted against allotment money, depending on the terms of the issue and the question. Calculate the excess carefully before recording entries.`],
["Exam method",`Show the allotment ratio, shares allotted to each applicant, application money received, application money required, excess adjusted/refunded, and journal entries. State any assumptions clearly.`]
]},
{ id:"a12-purchase",level:"Class 12",subject:"Accountancy",title:"Purchase consideration",chapter:"Company Accounts · Amalgamation",tags:"purchase consideration cash shares debentures net payment",summary:"Understand the amount paid by a purchasing company to acquire another business.",sections:[
["Meaning",`Purchase consideration is the amount or value of benefits agreed to be given by the purchasing company to the shareholders or owners of the vendor business for acquiring the business, as defined by the applicable accounting method and question.`],
["Possible forms",`It may be settled in cash, shares, debentures or another agreed form of consideration, subject to the transaction terms.`],
["Calculation",`Read the wording carefully. Depending on the stated method, consideration may be calculated using net payment, net assets or another prescribed method. Do not include every liability or expense automatically; follow the question's specified basis.`],
["Exam checklist",`List each item given, identify whether it forms part of consideration under the method used, calculate the total, and show the working note before journal entries.`]
]},
{ id:"e12-scarcity",level:"Class 12",subject:"Economics",title:"Scarcity, choice and allocation of resources",chapter:"Microeconomics · Basic concepts",tags:"scarcity choice allocation opportunity cost resources wants",summary:"Learn why scarcity makes economic choice necessary.",sections:[
["Scarcity",`Scarcity means that available resources are limited in relation to human wants. Since resources cannot satisfy every want at once, individuals and societies must make choices.`],
["Choice",`Choice is the selection of one option from alternatives. Choosing more of one good or activity often means giving up some of another.`],
["Allocation of resources",`Allocation is the way scarce resources such as land, labour, capital and entrepreneurship are distributed among competing uses.`],
["Opportunity cost",`Opportunity cost is the value of the next-best alternative forgone when a choice is made.`],
["Example",`If a student spends an hour revising Economics instead of Accountancy, the opportunity cost is the value of the best alternative use of that hour, such as Accountancy revision.`],
["Exam answer",`Scarcity arises because resources are limited while wants are many. It creates the need for choice and the allocation of resources among competing uses. Every choice may involve an opportunity cost.`]
]},
{ id:"e12-demand",level:"Class 12",subject:"Economics",title:"Demand and the law of demand",chapter:"Microeconomics · Demand",tags:"demand law demand price quantity inverse relationship demand curve",summary:"Revise the meaning of demand, its determinants and the usual demand relationship.",sections:[
["Meaning of demand",`Demand is the quantity of a good that consumers are willing and able to buy at different prices during a given period, other relevant conditions being specified.`],
["Law of demand",`Other things remaining constant, quantity demanded generally rises when price falls and falls when price rises. Thus price and quantity demanded have an inverse relationship in the usual case.`],
["Assumptions",`Income, tastes, prices of related goods, expectations and the number of consumers are assumed unchanged when describing movement along a demand curve.`],
["Determinants",`Important determinants include the good's own price, consumer income, tastes and preferences, prices of substitutes and complements, expectations and population.`],
["Movement and shift",`A change in the good's own price generally causes movement along the demand curve. A change in another determinant can shift the whole demand curve.`]
]},
{ id:"e12-monetary",level:"Class 12",subject:"Economics",title:"Expansionary monetary policy",chapter:"Macroeconomics · Monetary policy",tags:"expansionary monetary policy money supply interest rate investment aggregate demand",summary:"Explain the aim and possible effects of expansionary monetary policy.",sections:[
["Meaning",`Expansionary monetary policy is a policy stance in which a central bank uses measures intended to ease monetary and credit conditions and support economic activity.`],
["Common measures",`Depending on the economy and policy framework, measures may include reducing policy interest rates, buying securities, or easing reserve and liquidity conditions.`],
["Possible effects",`Lower borrowing costs can encourage consumption and investment, support aggregate demand and help economic activity during a downturn. Effects depend on confidence, banking conditions and other factors.`],
["Limitations",`If maintained too strongly or in unsuitable conditions, expansionary policy can add to inflationary pressure, encourage excessive borrowing or contribute to financial risks.`],
["Short exam answer",`Expansionary monetary policy refers to central-bank actions that ease monetary conditions to encourage borrowing, spending and investment, with the aim of supporting output and employment.`]
]},
{ id:"e12-monopoly",level:"Class 12",subject:"Economics",title:"Average revenue and marginal revenue under monopoly",chapter:"Microeconomics · Market structures",tags:"monopoly average revenue marginal revenue AR MR demand curve",summary:"Understand why marginal revenue is generally below average revenue for a monopolist facing a downward-sloping demand curve.",sections:[
["Average revenue (AR)",`Average revenue is total revenue divided by the quantity sold. It is the revenue earned per unit: AR = TR ÷ Q.`],
["Marginal revenue (MR)",`Marginal revenue is the change in total revenue from selling one additional unit: MR = change in TR ÷ change in Q.`],
["Why MR is below AR",`A monopolist normally faces a downward-sloping demand curve. To sell an additional unit, it generally has to lower the price; under a single-price model this lower price applies to earlier units too. Therefore the extra revenue from the added unit is less than the new price, so MR lies below AR.`],
["Important note",`The result is a standard model outcome, not a claim that every real-world pricing arrangement behaves identically.`]
]},
{ id:"e12-bank",level:"Class 12",subject:"Economics",title:"Development bank and capital market",chapter:"Macroeconomics · Financial institutions",tags:"development bank capital market long term finance shares bonds",summary:"Learn concise definitions and core functions.",sections:[
["Development bank",`A development bank is a financial institution established to provide finance and support for development priorities such as industry, infrastructure, agriculture or small businesses, according to its mandate.`],
["Functions of a development bank",`It may provide medium- and long-term loans, help finance productive projects, support priority sectors and offer project-related financial services.`],
["Capital market",`The capital market is the part of the financial system through which longer-term funds are raised and invested, commonly through instruments such as shares and bonds.`],
["Importance",`Capital markets can channel savings to businesses and governments, support investment and provide investors with opportunities to buy or sell financial securities, subject to regulation and risk.`]
]},
{ id:"e12-ppc",level:"Class 12",subject:"Economics",title:"Production Possibility Curve (PPC)",chapter:"Microeconomics · Basic concepts",tags:"PPC production possibility curve leftward shift opportunity cost scarcity diagram",summary:"Revise what a PPC shows and what a leftward shift may mean.",sections:[
["Meaning",`A Production Possibility Curve (PPC) shows the maximum combinations of two goods an economy can produce with given resources and technology when resources are used efficiently.`],
["Points and shape",`Points on the curve indicate productive efficiency; points inside indicate underused resources or inefficiency; points outside are currently unattainable with the stated resources and technology. A bowed-out curve illustrates increasing opportunity cost in the usual model.`],
["Leftward shift",`A leftward shift means productive capacity has decreased. Possible causes include destruction of capital, loss of labour, natural disasters or a decline in productive technology or resources.`],
["How to draw",`Draw labelled axes for Good X and Good Y. Draw the original PPC and a second curve closer to the origin. Label them PPC₁ and PPC₂ and write “decrease in productive capacity.”`],
["Exam answer",`A leftward shift of the PPC indicates a reduction in an economy's production capacity, possibly because of resource loss, damage to capital or adverse technological changes.`]
]},
{ id:"c12-function",level:"Class 12",subject:"Computer Science",title:"Functions in C programming",chapter:"C Programming · Functions",tags:"function C programming library user defined return type parameters syntax",summary:"Understand the purpose, types and basic syntax of C functions.",sections:[
["Meaning",`A function in C is a named block of code that performs a particular task. Functions help organise a program into reusable parts and make it easier to test and maintain.`],
["Types",`<ul><li><b>Library functions:</b> provided by standard libraries, such as printf() and scanf() from stdio.h, and strlen() from string.h.</li><li><b>User-defined functions:</b> written by the programmer for a specific task.</li></ul>`],
["General syntax",`<p class="definition"><code>return_type function_name(parameter_list) {<br> &nbsp;&nbsp;/* statements */<br> &nbsp;&nbsp;return value; /* when required */<br>}</code></p>`],
["Three common stages",`<ol><li><b>Declaration/prototype:</b> tells the compiler the function name, return type and parameters.</li><li><b>Function call:</b> transfers control to the function.</li><li><b>Definition:</b> contains the code that performs the task.</li></ol>`],
["Example",`<p class="definition"><code>int add(int a, int b) { return a + b; }</code></p><p>A call such as <code>add(2, 3)</code> returns <code>5</code>. The return type and arguments must be used consistently with the declaration.</p>`]
]},
{ id:"c12-dbms",level:"Class 12",subject:"Computer Science",title:"Database Management System (DBMS)",chapter:"Database · Fundamentals",tags:"DBMS database table record field advantages data integrity security",summary:"Revise the definition, benefits and common database terms.",sections:[
["Meaning",`A Database Management System (DBMS) is software used to define, create, store, retrieve, update and manage data in a database.`],
["Advantages",`<ul><li>Reduces unnecessary duplication when designed well.</li><li>Helps maintain consistency and integrity.</li><li>Supports controlled access and security.</li><li>Enables efficient querying and reporting.</li><li>Supports backup and recovery features.</li><li>Allows shared access under managed rules.</li></ul>`],
["Basic terms",`<ul><li><b>Table:</b> data arranged in rows and columns.</li><li><b>Record/row:</b> one complete entry about an item or entity.</li><li><b>Field/column:</b> one attribute, such as a student's name.</li><li><b>Primary key:</b> a field or set of fields that uniquely identifies a row.</li></ul>`],
["Limitations",`A DBMS can require cost, skilled administration, storage and careful security planning. A poorly managed database may still suffer from errors or unauthorised access.`]
]},
{ id:"c12-algorithm",level:"Class 12",subject:"Computer Science",title:"Algorithm and flowchart",chapter:"Programming · Problem solving",tags:"algorithm flowchart sequence decision symbols program logic",summary:"Learn how to describe program logic before writing code.",sections:[
["Algorithm",`An algorithm is a finite, ordered set of clear steps for solving a problem or completing a task.`],
["Characteristics",`A useful algorithm has clearly defined inputs and outputs where needed, unambiguous steps, a finite stopping point and steps that can be carried out.`],
["Flowchart",`A flowchart is a diagram that represents steps and decisions with standard symbols connected by arrows.`],
["Common symbols",`<ul><li><b>Oval:</b> start or end.</li><li><b>Rectangle:</b> processing or calculation.</li><li><b>Parallelogram:</b> input or output.</li><li><b>Diamond:</b> decision or condition.</li><li><b>Arrow:</b> direction of control flow.</li></ul>`],
["Exam tip",`For a flowchart question, use the standard symbols, label decisions clearly and ensure every path reaches an appropriate endpoint.`]
]},
{ id:"s12-population",level:"Class 12",subject:"Social Studies",title:"Population and demographic concepts",chapter:"Social Studies · Population",tags:"population census density growth birth death migration Nepal province",summary:"Revise key population terms and how to answer population questions accurately.",sections:[
["Population",`Population is the total number of people living in a defined area at a particular time.`],
["Census",`A population census is a systematic process of collecting, compiling and publishing demographic and related information about people in a country or area.`],
["Population density",`Population density is commonly calculated as total population divided by land area. Always check the units and the reference year.`],
["Population change",`Population changes through births, deaths and migration. Net migration is the difference between people entering and leaving an area over a period.`],
["Using statistics in answers",`When asked which province has the highest or lowest population, use the census year or dataset specified by your textbook or question. Rankings can differ by census year, so state the source year when possible.`]
]},
{ id:"s12-development",level:"Class 12",subject:"Social Studies",title:"Development and its indicators",chapter:"Social Studies · Development",tags:"development indicators education health income infrastructure human development",summary:"Understand development as broader than income alone.",sections:[
["Meaning",`Development is a process of improving people's quality of life and expanding opportunities. It includes economic, social, institutional and environmental dimensions.`],
["Economic indicators",`Common economic indicators include income per person, employment, production and access to productive opportunities.`],
["Social indicators",`Education, literacy, life expectancy, health services, sanitation and access to safe drinking water help show social progress.`],
["Human development",`Human development focuses on people's capabilities and opportunities, including living a long and healthy life, gaining knowledge and having a decent standard of living.`],
["Balanced development",`Sustainable and inclusive development seeks to improve wellbeing while considering inequalities, environmental limits and the needs of future generations.`]
]},
{ id:"s12-english-writing",level:"Class 12",subject:"English",title:"News story writing format",chapter:"English · Writing skills",tags:"news story headline byline dateline lead body conclusion who what when where why how",summary:"A simple structure for a clear school-level news story.",sections:[
["Structure",`<ol><li><b>Headline:</b> concise and informative.</li><li><b>Byline:</b> writer's name, if required.</li><li><b>Dateline:</b> place and date, according to your prescribed format.</li><li><b>Lead:</b> the most important facts, covering who, what, when and where where possible.</li><li><b>Body:</b> supporting facts, statements and context in descending order of importance.</li><li><b>Ending:</b> a final relevant fact or outcome.</li></ol>`],
["Writing tips",`Use factual language, short paragraphs, a suitable headline and the correct tense. Do not invent quotations or facts in a real news report.`],
["Practice checklist",`Before submitting, check the headline, core facts, paragraph order, spelling, grammar and any word limit given in the question.`]
]},
{ id:"s12-event",level:"Class 12",subject:"English",title:"Event description and letter to the editor",chapter:"English · Writing skills",tags:"event description letter editor address date subject salutation body",summary:"Review the purpose and key structure of two common writing tasks.",sections:[
["Event description",`Describe what happened, where and when it happened, who participated, the main activities and the outcome. Arrange details in a logical order and use specific but truthful observations.`],
["Letter to the editor",`A typical school format includes the writer's address and date, the editor's address, subject, salutation, a concise introduction of the issue, supporting points, a respectful request or recommendation, and a closing with the writer's name. Follow the format taught by your teacher or examination board.`],
["Formal style",`Use polite, clear language. State the purpose early, support claims with reasons or examples, and avoid personal attacks.`]
]},
{ id:"entrance-reasoning",level:"Entrance",subject:"Entrance Preparation",title:"Logical reasoning: number patterns",chapter:"Entrance Practice · Reasoning",tags:"entrance CEE IOE MCQ reasoning sequence number pattern",summary:"A starter revision guide for recognising common number sequences.",sections:[
["Common patterns",`Check whether terms increase by a constant difference, multiply by a constant, alternate between two rules, or follow squares, cubes or another familiar sequence.`],
["Worked example",`Sequence: 3, 6, 9, 12, __. Each term increases by 3, so the next term is 15.`],
["Practice strategy",`Calculate differences first, then ratios where appropriate. If neither works, test alternating terms or familiar powers. Avoid guessing before checking the pattern.`],
["Study note",`This is general reasoning practice, not an official or complete CEE/IOE question bank. Confirm the entrance exam syllabus and format from current official notices.`]
]},
{ id:"entrance-study",level:"Entrance",subject:"Entrance Preparation",title:"Entrance exam study strategy",chapter:"Entrance Practice · Study planning",tags:"entrance exam timetable practice mock test error log revision",summary:"A practical framework for organising entrance preparation.",sections:[
["Plan the syllabus",`List each subject and topic, then mark topics as not started, learning, or revision. Prioritise topics using the official syllabus and your own practice results.`],
["Active practice",`Alternate concept review with question practice. After checking answers, write down why a mistake happened and revisit that concept later.`],
["Timed mock tests",`Use practice tests under the time limits stated by the relevant exam. Review accuracy, time management and repeated errors; do not only count the score.`],
["Weekly review",`At the end of each week, revisit difficult topics, adjust your plan and keep enough time for rest and school coursework.`]
]},
{ id:"a11-accounting",level:"Class 11",subject:"Accountancy",title:"Accounting equation",chapter:"Class 11 · Accounting fundamentals",tags:"assets liabilities capital accounting equation",summary:"Learn the foundation that connects assets, liabilities and owner's capital.",sections:[
["Equation",`Assets = Liabilities + Capital. The equation expresses that resources are financed either by claims of outsiders or by the owner's claim.`],
["Assets",`Assets are resources controlled by a business, such as cash, inventory, equipment and amounts receivable.`],
["Liabilities",`Liabilities are obligations owed to outsiders, such as loans and amounts payable to suppliers.`],
["Capital",`Capital is the owner's residual interest in the business after liabilities are deducted from assets. Profit, loss and drawings can change capital.`],
["Example",`If a business has assets of Rs. 100,000 and liabilities of Rs. 25,000, capital is Rs. 75,000 because 100,000 = 25,000 + 75,000.`]
]},
{ id:"a11-trial",level:"Class 11",subject:"Accountancy",title:"Trial balance",chapter:"Class 11 · Accounting process",tags:"trial balance debit credit ledger balances errors",summary:"Revise the purpose and limitations of a trial balance.",sections:[
["Meaning",`A trial balance is a statement listing ledger account balances at a particular date, with debit and credit columns used to check their arithmetic agreement.`],
["Objectives",`It helps check whether total debit balances equal total credit balances, provides a summary of ledger balances and supports preparation of financial statements.`],
["Limitations",`Agreement does not prove that every entry is correct. Errors of omission, errors of principle and some compensating errors may remain undetected.`],
["Preparation",`Balance ledger accounts, list debit and credit balances in their appropriate columns, total each column and investigate any difference.`]
]},
{ id:"e11-demand",level:"Class 11",subject:"Economics",title:"Basic economic problem",chapter:"Class 11 · Introduction to Economics",tags:"scarcity choice opportunity cost basic economic problem",summary:"Understand the basic questions every economy must address.",sections:[
["Why the problem exists",`Human wants are numerous, but productive resources are limited and have alternative uses. This creates scarcity and makes choice necessary.`],
["Three basic questions",`<ul><li>What goods and services should be produced, and in what quantities?</li><li>How should they be produced?</li><li>For whom should they be produced?</li></ul>`],
["Opportunity cost",`Opportunity cost is the value of the next-best alternative given up when choosing one option over another.`],
["Exam answer",`The basic economic problem arises from unlimited wants and scarce resources with alternative uses. Every economy must decide what to produce, how to produce and for whom to produce.`]
]},
{ id:"c11-computer",level:"Class 11",subject:"Computer Science",title:"Computer system: basic concepts",chapter:"Class 11 · Computer fundamentals",tags:"computer hardware software input output storage CPU",summary:"Review the main parts of a computer system.",sections:[
["Computer system",`A computer system accepts data as input, processes it according to instructions, stores data or results, and produces information as output.`],
["Hardware",`Hardware is the physical equipment, such as the keyboard, monitor, processor, storage drive and printer.`],
["Software",`Software is the set of programs and instructions used to operate the computer or perform tasks. Operating systems and application programs are common categories.`],
["IPOS cycle",`Input → Processing → Output → Storage is a simple way to remember the basic information-processing cycle. Storage can be involved at several stages.`]
]},
{ id:"s11-society",level:"Class 11",subject:"Social Studies",title:"Society, culture and socialisation",chapter:"Class 11 · Society and social life",tags:"society culture norms values socialisation family school",summary:"Learn how social life and culture shape human behaviour.",sections:[
["Society",`Society is a network of people who interact, share social relationships and organise aspects of their common life through institutions and norms.`],
["Culture",`Culture includes shared values, beliefs, language, customs, knowledge, arts and ways of life learned and transmitted within a group.`],
["Socialisation",`Socialisation is the lifelong process through which people learn the norms, values, roles and behaviours of their society.`],
["Agents",`Family, school, peer groups, community, media and other institutions can influence socialisation.`]
]},
{ id:"english-grammar",level:"Class 12",subject:"English",title:"Grammar revision checklist",chapter:"English · Grammar",tags:"grammar tense subject verb agreement voice reported speech articles prepositions",summary:"A checklist for revising common English grammar areas.",sections:[
["Subject–verb agreement",`A verb should agree with its subject in number and person. Identify the main subject rather than being distracted by words between the subject and verb.`],
["Tense consistency",`Choose a tense that matches the time and meaning, and keep it consistent unless the time frame changes.`],
["Articles",`Use a/an with singular countable nouns when appropriate, the for specific or identifiable references, and no article for some general plural or uncountable uses.`],
["Voice and reported speech",`When changing active to passive voice, preserve the tense and object meaning. In reported speech, adjust pronouns, tense and time expressions where the context requires it.`],
["Practice method",`Read the full sentence, identify its grammatical role, apply the rule, and reread the corrected sentence for meaning.`]
]}

,{id:"a11-accounting-equation",level:"Class 11",subject:"Accountancy",title:"Accounting equation",chapter:"Fundamentals of Accounting",tags:"assets liabilities capital equation",summary:"Revise the relationship among assets, liabilities and capital with simple examples.",sections:[["Meaning",`The accounting equation expresses the relationship between what a business owns, what it owes, and the owner's claim.`],["Formula",`<div class="definition"><b>Assets = Liabilities + Capital</b></div>`],["Example",`If a business has assets of Rs. 100,000 and liabilities of Rs. 30,000, capital is Rs. 70,000 (100,000 − 30,000).`],["Importance",`It is the foundation of double-entry bookkeeping and helps check that the accounting records remain balanced.`]]}
,{id:"a11-journal",level:"Class 11",subject:"Accountancy",title:"Journal and journal entries",chapter:"Fundamentals of Accounting",tags:"journal debit credit transactions",summary:"Understand the journal as the book of original entry and review the debit-credit approach.",sections:[["Meaning",`A journal is the book in which business transactions are first recorded in chronological order.`],["Parts",`A journal entry commonly includes date, particulars, ledger folio where used, debit amount and credit amount.`],["Rules",`Identify the accounts affected, classify them, apply the relevant debit-credit rules and make sure total debit equals total credit.`],["Exam method",`Write the date, debit account, credit account with narration, and show amounts in the correct columns.`]]}
,{id:"e11-demand",level:"Class 11",subject:"Economics",title:"Demand and law of demand",chapter:"Microeconomics",tags:"demand price quantity curve",summary:"Learn demand, the law of demand and factors that shift demand.",sections:[["Meaning of demand",`Demand is the quantity of a good consumers are willing and able to buy at different prices during a given period, other things remaining equal.`],["Law of demand",`Other things equal, quantity demanded generally rises when price falls and falls when price rises.`],["Determinants",`Income, tastes, prices of related goods, expectations and number of buyers can affect demand.`],["Movement and shift",`A price change generally causes movement along a demand curve. A change in a non-price determinant can shift the curve.`]]}
,{id:"e12-national-income",level:"Class 12",subject:"Economics",title:"National income: basic concepts",chapter:"Macroeconomics",tags:"GDP GNP NNP national income",summary:"Distinguish major national-income terms and revise why national income is measured.",sections:[["GDP",`Gross Domestic Product (GDP) is the value of final goods and services produced within a country's domestic territory during a given period.`],["GNP",`Gross National Product (GNP) adjusts GDP for net factor income from abroad in the conventional textbook framework.`],["Why measure it?",`National-income estimates help assess economic performance, compare periods and support planning and policy decisions.`],["Exam caution",`Use the exact definitions, symbols and adjustments taught in your current NEB textbook because accounting conventions and syllabus wording matter.`]]}
,{id:"c11-algorithm-flowchart",level:"Class 11",subject:"Computer Science",title:"Algorithm and flowchart",chapter:"Programming concepts",tags:"algorithm flowchart symbols input process output",summary:"Revise the meaning, qualities and common symbols used in flowcharts.",sections:[["Algorithm",`An algorithm is a finite, ordered set of clear steps used to solve a problem.`],["Good algorithm",`A good algorithm has clear steps, defined inputs and outputs, terminates after a finite number of steps and produces the intended result.`],["Flowchart symbols",`Oval: start or stop; parallelogram: input or output; rectangle: processing; diamond: decision; arrows: flow direction.`],["Benefits",`Algorithms and flowcharts help plan, communicate, test and debug a program before coding.`]]}
,{id:"c12-arrays",level:"Class 12",subject:"Computer Science",title:"Arrays in C",chapter:"C Programming",tags:"array index element declaration",summary:"Understand how arrays store multiple values of the same type in indexed positions.",sections:[["Meaning",`An array stores a fixed number of values of the same data type under one name.`],["Declaration",`Example: <code>int marks[5];</code> declares an integer array with five elements.`],["Indexing",`C array indexing starts at 0, so a five-element array uses indexes 0 through 4.`],["Example",`<pre><code>int a[3] = {10, 20, 30};
printf("%d", a[0]);</code></pre> prints 10.`]]}
,{id:"s12-development",level:"Class 12",subject:"Social Studies",title:"Concept of development",chapter:"Development and infrastructure",tags:"development indicators quality of life",summary:"Revise development as a multidimensional process and examples of indicators.",sections:[["Meaning",`Development is a process of improving people's living conditions, opportunities, capabilities and overall well-being.`],["Dimensions",`Economic growth, education, health, equality, participation, environmental sustainability and access to services are relevant dimensions.`],["Indicators",`Income per person, literacy, life expectancy, employment and access to safe water can help describe development, but no single indicator tells the whole story.`],["Nepal context",`When discussing Nepal, use current and verifiable statistics from the prescribed textbook or official publications.`]]}
,{id:"en12-event-description",level:"Class 12",subject:"English",title:"Writing an event description",chapter:"Writing skills",tags:"event description date place participants sequence",summary:"Use a clear structure to describe a school event in an organised paragraph.",sections:[["Structure",`Start with the event name, date and venue. Introduce the organiser and purpose, describe the main activities in sequence, then conclude with the outcome or significance.`],["Language",`Use past tense for a completed event, specific details, logical connectors and objective wording.`],["Checklist",`Include what happened, when and where it happened, who participated, the highlights and the result. Do not invent facts if you are reporting a real event.`]]}

,{id:"e12-monetary-policy",level:"Class 12",subject:"Economics",title:"Monetary policy and its instruments",chapter:"Macroeconomics · Money and Banking",tags:"monetary policy central bank bank rate reserve ratio open market operations inflation",summary:"Revise the meaning of monetary policy and common tools used by a central bank.",sections:[["Meaning",`Monetary policy refers to measures taken by a country's central bank to influence money, credit and financial conditions in pursuit of objectives such as price stability and sustainable economic activity.`],["Expansionary policy",`An expansionary stance aims to support borrowing and economic activity, for example by lowering relevant policy rates or easing liquidity conditions when appropriate.`],["Contractionary policy",`A contractionary stance aims to reduce inflationary pressure by tightening financial conditions, for example through higher policy rates or reduced liquidity.`],["Common instruments",`Depending on the country's framework, instruments may include policy or bank rates, reserve requirements, open market operations and liquidity facilities.`],["Exam answer",`Monetary policy is the central bank's use of monetary and credit instruments to influence economic conditions. Explain each instrument using the terminology in the current textbook.`]]}
,{id:"e12-market-equilibrium",level:"Class 12",subject:"Economics",title:"Market equilibrium: demand and supply",chapter:"Microeconomics · Market",tags:"equilibrium demand supply price excess demand excess supply",summary:"Understand equilibrium price and quantity and how markets adjust when there is a shortage or surplus.",sections:[["Meaning",`Market equilibrium occurs where quantity demanded equals quantity supplied at a particular price, other things remaining equal.`],["Equilibrium price",`The equilibrium price is the price at which buyers' planned purchases match sellers' planned sales. The corresponding amount is the equilibrium quantity.`],["Excess demand",`If price is below equilibrium, quantity demanded may exceed quantity supplied. This shortage can put upward pressure on price.`],["Excess supply",`If price is above equilibrium, quantity supplied may exceed quantity demanded. This surplus can put downward pressure on price.`],["Diagram tip",`Draw price on the vertical axis and quantity on the horizontal axis. Show a downward-sloping demand curve and an upward-sloping supply curve; label their intersection E.`]]}
,{id:"a12-cash-flow",level:"Class 12",subject:"Accountancy",title:"Cash flow statement: basic classification",chapter:"Financial Statements",tags:"cash flow operating investing financing inflows outflows",summary:"Classify cash flows into operating, investing and financing activities for revision questions.",sections:[["Meaning",`A cash flow statement summarises cash and cash-equivalent inflows and outflows during an accounting period.`],["Operating activities",`These are the principal revenue-producing activities of the entity and other activities that are not investing or financing activities.`],["Investing activities",`These generally involve acquiring and disposing of long-term assets and investments not treated as cash equivalents.`],["Financing activities",`These activities change the size or composition of contributed equity and borrowings, such as proceeds from issuing shares or taking loans and repayments of borrowings.`],["Exam method",`Classify each transaction first, then follow the indirect or direct method and format prescribed in the question and textbook.`]]}
,{id:"a12-cash-book",level:"Class 12",subject:"Accountancy",title:"Cash book and bank column",chapter:"Accounting Process",tags:"cash book cash bank debit credit contra entry",summary:"Review the purpose of a cash book and the meaning of common cash and bank entries.",sections:[["Meaning",`A cash book records cash and, where included, bank transactions. It serves as both a book of original entry and a ledger account for the balances it contains.`],["Cash column",`Cash received is entered on the debit or receipts side, while cash payments are entered on the credit or payments side.`],["Bank column",`Bank receipts and payments are recorded in the bank column. The exact treatment of overdrafts and adjustments should follow the format taught in class.`],["Contra entry",`A transfer between cash and bank, such as cash deposited into the bank, affects both columns and is commonly marked as a contra entry in a double-column cash book.`],["Check",`Keep the dates, particulars, folio and amounts aligned with the prescribed format, and balance the columns carefully.`]]}
,{id:"c12-pointers",level:"Class 12",subject:"Computer Science",title:"Pointers in C",chapter:"C Programming · Functions and pointers",tags:"pointer address dereference ampersand asterisk call by reference",summary:"Learn what a pointer stores, how to declare one and how address and dereference operators work.",sections:[["Definition",`A pointer is a variable that stores the memory address of another object of a compatible type.`],["Declaration",`Example: <code>int n = 10; int *p = &n;</code> declares an integer pointer p and stores the address of n in it.`],["Operators",`The address-of operator <code>&</code> obtains an object's address. The unary dereference operator <code>*</code> accesses the object pointed to, when the pointer is valid.`],["Example",`<pre><code>int n = 10;
int *p = &n;
printf("%d", *p);</code></pre> prints 10 because <code>*p</code> accesses the value stored in n.`],["Care",`Initialise pointers before use and never dereference a null, uninitialised, dangling or otherwise invalid pointer.`]]}
,{id:"c12-functions",level:"Class 12",subject:"Computer Science",title:"Functions in C: declaration, definition and call",chapter:"C Programming · Functions",tags:"function prototype definition call arguments return value",summary:"Revise the parts of a user-defined function and why programs use functions.",sections:[["Meaning",`A function is a named block of code designed to perform a particular task. Functions help organise programs, reuse logic and make testing easier.`],["Three common parts",`A declaration or prototype tells the compiler the function's name, return type and parameter types. The definition contains the function body. A function call requests that the function execute.`],["Example",`<pre><code>int add(int a, int b);  // prototype
int add(int a, int b) { return a + b; }
// Example call: add(2, 3)</code></pre>`],["Parameters and return",`Parameters receive values for a function to work with. A non-void function can return a result using <code>return</code>; a void function does not return a value.`],["Exam tip",`When asked to write a program, include the required header files, correct function prototype where needed, main function and clear output.`]]}
,{id:"s12-federalism",level:"Class 12",subject:"Social Studies",title:"Federalism and levels of government in Nepal",chapter:"Constitution and Governance",tags:"federalism federal provincial local government Nepal powers",summary:"Explain federalism and describe the three levels of government in Nepal.",sections:[["Meaning",`Federalism is a system in which constitutional authority is shared between different levels of government.`],["Three levels",`Nepal has federal, provincial and local levels of government. Their powers and responsibilities are allocated by the Constitution and relevant laws.`],["Why it matters",`Federalism can bring decision-making closer to communities, support inclusion and allow different levels to address local needs, while requiring coordination and accountability.`],["Challenges",`Possible challenges include overlapping responsibilities, uneven capacity, resource distribution, coordination problems and delays in service delivery.`],["Exam method",`Define federalism, name the three levels, explain two benefits and two challenges, and use constitutional terminology accurately.`]]}
,{id:"s12-development-indicators",level:"Class 12",subject:"Social Studies",title:"Indicators of human development",chapter:"Development and Quality of Life",tags:"human development HDI health education income life expectancy literacy",summary:"Review how health, education and income indicators are used to assess human development.",sections:[["Meaning",`Human development focuses on expanding people's capabilities and opportunities so they can lead healthy, knowledgeable and dignified lives.`],["Health",`Life expectancy and access to health services can help describe health outcomes.`],["Education",`Indicators can include expected years of schooling, mean years of schooling, literacy or school participation, depending on the framework.`],["Income",`Income per person is often used as an indicator of material living standards, but income alone cannot represent every aspect of well-being.`],["Limitation",`A composite index summarises selected dimensions but may hide inequalities within a country. Use the data year and source whenever quoting statistics.`]]}
,{id:"en12-letter-editor",level:"Class 12",subject:"English",title:"Letter to the editor: exam format",chapter:"Writing Skills · Formal Letters",tags:"letter editor format subject salutation issue recommendation",summary:"Use a clear formal structure to raise a public issue and suggest practical solutions.",sections:[["Structure",`Write the sender's address and date if required by your format, the editor or newspaper address where taught, a subject line, salutation, body and complimentary close with your name.`],["Opening",`State the issue clearly and explain why it matters to the community. Avoid an unnecessarily long introduction.`],["Body",`Describe relevant causes or effects using accurate details. Organise points into short paragraphs and keep the tone respectful.`],["Recommendation",`Suggest realistic steps for the responsible authority, community or public. Make sure recommendations follow from the issue discussed.`],["Final checklist",`Check the format, date, subject, paragraphing, formal language, grammar and word limit required by the question.`]]}

];
